class Solution { public int numberOfSets(int n,int maxDistance,int[][] roads){final int INF=1000000000;int answer=0;for(int mask=0;mask<(1<<n);mask++){int[][] distance=new int[n][n];for(int i=0;i<n;i++){Arrays.fill(distance[i],INF);distance[i][i]=0;}for(int[] road:roads)if((mask>>road[0]&1)==1&&(mask>>road[1]&1)==1){distance[road[0]][road[1]]=Math.min(distance[road[0]][road[1]],road[2]);distance[road[1]][road[0]]=Math.min(distance[road[1]][road[0]],road[2]);}for(int middle=0;middle<n;middle++)if((mask>>middle&1)==1)for(int from=0;from<n;from++)if((mask>>from&1)==1)for(int to=0;to<n;to++)if((mask>>to&1)==1)distance[from][to]=Math.min(distance[from][to],distance[from][middle]+distance[middle][to]);boolean valid=true;for(int i=0;i<n&&valid;i++)if((mask>>i&1)==1)for(int j=i+1;j<n;j++)if((mask>>j&1)==1&&distance[i][j]>maxDistance){valid=false;break;}if(valid)answer++;}return answer;} }
